<?php
require_once __DIR__.'/includes/bootstrap.php';require_role(['Administrator']);$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';
 if($action==='create'){$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$pass=$_POST['password']??'';$role=$_POST['role']??'';$email=trim($_POST['email']??'');
 if($name===''||$username===''||strlen($pass)<10||!in_array($role,['Administrator','SACCO Official','Driver','Conductor'],true))$errors[]='Enter a name, username, valid role and password of at least 10 characters.';
 else{try{$pdo->prepare('INSERT INTO users(full_name,username,password,role,email,status) VALUES(?,?,?,?,?,"Active")')->execute([$name,$username,password_hash($pass,PASSWORD_DEFAULT),$role,$email?:null]);$id=(int)$pdo->lastInsertId();audit_log($pdo,'user.created','user',$id,'Created account '.$username);flash('User account created.');header('Location: users.php');exit;}catch(PDOException $e){$errors[]=$e->getCode()==='23000'?'That username is already in use.':'Unable to create the account.';}}}
 if($action==='status'){$id=(int)($_POST['user_id']??0);if($id!==(int)current_user()['id']){$status=$_POST['status']==='Inactive'?'Inactive':'Active';$pdo->prepare('UPDATE users SET status=? WHERE user_id=?')->execute([$status,$id]);audit_log($pdo,'user.status_changed','user',$id,'Account status set to '.$status);flash('Account status updated.');header('Location: users.php');exit;}}
}
$rows=fetch_all($pdo,'SELECT user_id,full_name,username,role,email,status,created_at FROM users ORDER BY created_at DESC');
page_header('User access');show_errors($errors);
echo '<div class="split"><section class="card"><div class="card-head"><div><h2>Create an account</h2><p>Invite a team member with the right level of access.</p></div></div><form method="post">'.csrf_field().'<input type="hidden" name="action" value="create"><div class="field"><label>Full name</label><input name="full_name" required></div><div class="field" style="margin-top:12px"><label>Username</label><input name="username" required></div><div class="field" style="margin-top:12px"><label>Email (optional)</label><input type="email" name="email"></div><div class="field" style="margin-top:12px"><label>Role</label><select name="role"><option>Administrator</option><option>SACCO Official</option><option>Driver</option><option>Conductor</option></select></div><div class="field" style="margin-top:12px"><label>Temporary password</label><input type="password" name="password" minlength="10" required><small class="muted">Use at least 10 characters. Share it securely.</small></div><div class="form-actions"><button type="submit">＋ Create user</button></div></form></section>';
echo '<section class="card"><div class="card-head"><div><h2>Access policy</h2><p>Role-based access is checked on the server for each protected page.</p></div></div><div style="display:grid;gap:12px"><div><b>Administrator</b><p class="muted">Full configuration, user access, reporting and operational controls.</p></div><div><b>SACCO Official</b><p class="muted">Fleet, staff, routes, trips, passengers, complaints and reports.</p></div><div><b>Driver</b><p class="muted">Assigned trip information and relevant operational views.</p></div><div><b>Conductor</b><p class="muted">Trip recording and authorised passenger operations.</p></div></div></section></div>';
echo '<section class="card"><div class="card-head"><div><h2>Team accounts</h2><p>'.count($rows).' registered accounts</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th>Access</th></tr></thead><tbody>';
foreach($rows as $r){echo '<tr><td><b>'.e($r['full_name']).'</b><br><small class="muted">'.e($r['email']??'').'</small></td><td>'.e($r['username']).'</td><td>'.e($r['role']).'</td><td><span class="pill '.strtolower($r['status']).'">'.e($r['status']).'</span></td><td>'.e(substr($r['created_at'],0,10)).'</td><td>';if((int)$r['user_id']!==(int)current_user()['id'])echo '<form method="post" class="inline">'.csrf_field().'<input type="hidden" name="action" value="status"><input type="hidden" name="user_id" value="'.(int)$r['user_id'].'"><input type="hidden" name="status" value="'.($r['status']==='Active'?'Inactive':'Active').'"><button class="btn secondary small" type="submit">'.($r['status']==='Active'?'Deactivate':'Activate').'</button></form>';else echo '<span class="muted">Current user</span>';echo '</td></tr>';}
echo '</tbody></table></div></section>';page_footer();
